pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(unlockTime > block.timestamp && unlockTime < type(uint256).max);
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (uint storedUnlockTime,) = c.Acc(actor);
        assertTrue(storedUnlockTime >= unlockTime);
    }
}
